lib='''def one_color_rows(grid):
    """Indices of rows that are a single color throughout."""
    return [i for i, row in enumerate(grid) if len(set(row)) == 1]

def one_color_cols(grid):
    """Indices of columns that are a single color throughout."""
    return [j for j in range(len(grid[0])) if len({row[j] for row in grid}) == 1]

def segments(lines, n):
    """Contiguous index runs of range(n) that skip the given line indices."""
    out, cur = [], []
    for i in range(n):
        if i in lines:
            if cur: out.append(cur); cur = []
        else:
            cur.append(i)
    if cur: out.append(cur)
    return out

def background(grid):
    """The most frequent color in the grid."""
    return max({v for row in grid for v in row}, key=lambda c: sum(row.count(c) for row in grid))

def blocks(grid):
    """The subgrids between one-color frontier rows and columns, as (rows, cols) index lists."""
    return segments(one_color_rows(grid), len(grid)), segments(one_color_cols(grid), len(grid[0]))

def parity_summary(grid, sep, odd_value=None):
    """Split the grid by sep-colored frontier lines; each block becomes 1 if it holds an even number of the special (non-background) color, else the odd_value (default: the background color)."""
    bg = background(grid)
    ov = bg if odd_value is None else odd_value
    rs, cs = blocks(grid)
    specials = {v for row in grid for v in row} - {bg, sep}
    sp = min(specials) if specials else bg
    return [[ov if sum(grid[i][j] == sp for i in R for j in C) % 2 else 1 for C in cs] for R in rs]
